import json
from itertools import permutations

def solve_puzzle():
    # Input variables
    houses = [1, 2, 3, 4, 5, 6]
    names = ["Alice", "Arnold", "Carol", "Peter", "Bob", "Eric"]
    phone_models = ["huawei p50", "iphone 13", "xiaomi mi 11", "oneplus 9", "samsung galaxy s21", "google pixel 6"]

    # Indices convenience (0-based)
    H1, H2, H3, H4, H5, H6 = 0, 1, 2, 3, 4, 5

    # Constraints helpers for names
    def names_valid_partial(assign):
        # assign: list of length 6, entries are names or None

        # Fixed names from clues:
        # 7: Huawei P50 user is Eric -> with clue 2, Eric is in first house
        if assign[H1] is not None and assign[H1] != "Eric":
            return False
        # 10: Arnold uses OnePlus 9 -> with clue 3, Arnold is in the sixth house
        if assign[H6] is not None and assign[H6] != "Arnold":
            return False

        # 6: There is one house between Bob and Carol -> positions differ by 2
        pos_bob = None
        pos_carol = None
        for i, n in enumerate(assign):
            if n == "Bob":
                pos_bob = i
            if n == "Carol":
                pos_carol = i
        if pos_bob is not None and pos_carol is not None:
            if abs(pos_bob - pos_carol) != 2:
                return False
        elif pos_bob is not None:
            # ensure Carol can still be placed at distance 2
            possible = []
            if pos_bob - 2 >= 0 and assign[pos_bob - 2] in (None, "Carol"):
                possible.append(pos_bob - 2)
            if pos_bob + 2 < 6 and assign[pos_bob + 2] in (None, "Carol"):
                possible.append(pos_bob + 2)
            if not possible:
                return False
        elif pos_carol is not None:
            # ensure Bob can still be placed at distance 2
            possible = []
            if pos_carol - 2 >= 0 and assign[pos_carol - 2] in (None, "Bob"):
                possible.append(pos_carol - 2)
            if pos_carol + 2 < 6 and assign[pos_carol + 2] in (None, "Bob"):
                possible.append(pos_carol + 2)
            if not possible:
                return False

        # 9: Alice is somewhere to the left of Carol
        pos_alice = None
        for i, n in enumerate(assign):
            if n == "Alice":
                pos_alice = i
        if pos_alice is not None and pos_carol is not None:
            if not (pos_alice < pos_carol):
                return False
        elif pos_alice is not None:
            # Ensure there is still room for Carol to the right
            right_slots = [i for i in range(pos_alice + 1, 6) if assign[i] in (None, "Carol")]
            if not right_slots:
                return False
        elif pos_carol is not None:
            # Ensure there is still room for Alice to the left
            left_slots = [i for i in range(0, pos_carol) if assign[i] in (None, "Alice")]
            if not left_slots:
                return False

        return True

    # Backtracking for names
    def assign_names():
        assign = [None] * 6
        # Fixed from clues
        assign[H1] = "Eric"    # 7 & 2
        assign[H6] = "Arnold"  # 10 & 3

        remaining = [n for n in names if n not in ("Eric", "Arnold")]

        # We'll fill houses in an order for pruning (skip fixed)
        order = [H2, H3, H4, H5]

        def backtrack(idx, assign, remaining):
            if idx == len(order):
                if names_valid_partial(assign) and all(x is not None for x in assign):
                    return assign[:]
                return None

            h = order[idx]
            for n in list(remaining):
                assign[h] = n
                if names_valid_partial(assign):
                    new_remaining = [x for x in remaining if x != n]
                    result = backtrack(idx + 1, assign, new_remaining)
                    if result is not None:
                        return result
                assign[h] = None
            return None

        return backtrack(0, assign, remaining)

    name_assignment = assign_names()
    if name_assignment is None:
        raise RuntimeError("No valid assignment for names found.")

    # Backtracking for models
    def models_valid_partial(models_assign):
        # models_assign: list of length 6, entries are model or None

        # 2: Huawei P50 is in the first house
        if models_assign[H1] is not None and models_assign[H1] != "huawei p50":
            return False
        # 7: Huawei P50 user is Eric -> ensure that if a house has 'huawei p50', its name is Eric, and if name is Eric, model is huawei p50
        if models_assign[H1] is not None and models_assign[H1] == "huawei p50":
            if name_assignment[H1] != "Eric":
                return False
        if name_assignment[H1] == "Eric" and models_assign[H1] is not None and models_assign[H1] != "huawei p50":
            return False

        # 3: OnePlus 9 is in the sixth house
        if models_assign[H6] is not None and models_assign[H6] != "oneplus 9":
            return False
        # 10: Arnold uses a OnePlus 9
        if name_assignment[H6] == "Arnold" and models_assign[H6] is not None and models_assign[H6] != "oneplus 9":
            return False

        # 8: Xiaomi Mi 11 is in the third house
        if models_assign[H3] is not None and models_assign[H3] != "xiaomi mi 11":
            return False

        # 4: Google Pixel 6 is not in the second house
        if models_assign[H2] == "google pixel 6":
            return False

        # 5: iPhone 13 is not in the second house
        if models_assign[H2] == "iphone 13":
            return False

        # 1: The person who uses an iPhone 13 is Alice
        # Enforce both ways as far as assigned
        for i in range(6):
            if models_assign[i] == "iphone 13" and name_assignment[i] != "Alice":
                return False
            if name_assignment[i] == "Alice" and models_assign[i] is not None and models_assign[i] != "iphone 13":
                return False

        return True

    def assign_models():
        models_assign = [None] * 6

        # Fixed from clues
        models_assign[H1] = "huawei p50"     # clue 2
        models_assign[H6] = "oneplus 9"      # clue 3
        models_assign[H3] = "xiaomi mi 11"   # clue 8

        # Also from clue 1: If we know where Alice is, that house must be iPhone 13
        alice_pos = name_assignment.index("Alice")
        # But ensure we don't overwrite fixed ones; logic should not conflict
        if models_assign[alice_pos] is not None and models_assign[alice_pos] != "iphone 13":
            return None  # conflict; no solution
        models_assign[alice_pos] = "iphone 13"

        remaining_models = [m for m in phone_models if m not in models_assign]

        # Houses order to fill remaining models
        order = [i for i in range(6) if models_assign[i] is None]

        def domain_for_house(h, used_models_set):
            # Start with remaining models
            dom = set(phone_models) - used_models_set
            # Fixed positions constraints
            if h == H1:
                dom &= {"huawei p50"}
            if h == H6:
                dom &= {"oneplus 9"}
            if h == H3:
                dom &= {"xiaomi mi 11"}
            # House 2 exclusions
            if h == H2:
                dom -= {"google pixel 6", "iphone 13"}
            # Link constraints from names
            if name_assignment[h] == "Alice":
                dom &= {"iphone 13"}
            if name_assignment[h] == "Eric":
                dom &= {"huawei p50"}
            if name_assignment[h] == "Arnold":
                dom &= {"oneplus 9"}
            return dom

        def backtrack(idx, models_assign):
            if idx == len(order):
                if models_valid_partial(models_assign) and all(x is not None for x in models_assign):
                    return models_assign[:]
                return None

            h = order[idx]
            used = set(x for x in models_assign if x is not None)
            dom = domain_for_house(h, used)

            for m in list(dom):
                models_assign[h] = m
                if models_valid_partial(models_assign):
                    res = backtrack(idx + 1, models_assign)
                    if res is not None:
                        return res
                models_assign[h] = None
            return None

        # Quick feasibility check for current fixed
        if not models_valid_partial(models_assign):
            return None

        return backtrack(0, models_assign)

    model_assignment = assign_models()
    if model_assignment is None:
        raise RuntimeError("No valid assignment for phone models found.")

    # Prepare JSON output
    rows = []
    for i in range(6):
        rows.append([str(i + 1), name_assignment[i], model_assignment[i]])

    output = {
        "solution": {
            "header": ["House", "Name", "PhoneModel"],
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    solution = solve_puzzle()
    print(json.dumps(solution, ensure_ascii=False, indent=2))
